use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [doc = " Main entry point for eager splitting of a crate"] pub fn eager_split_crate (paths : & CratePaths , config : & SplitDeclsConfig) -> Result < Vec < ModuleNotFoundReport > > { println ! ("🚀 STARTING CRATE PROCESSING: {}" , paths . crate_name) ; println ! ("   📂 Crate path: {}" , paths . crate_path . display ()) ; println ! ("   📄 Source files: {:?}" , paths . source_files . iter () . map (| p | p . display () . to_string ()) . collect ::< Vec < _ >> ()) ; println ! ("   📁 Output directory: {}" , paths . decls_output_dir . display ()) ; let mut module_not_found_errors : Vec < ModuleNotFoundReport > = Vec :: new () ; let mut collected_module_names : Vec < Ident > = Vec :: new () ; let mut item_count : usize = 0 ; let common_uses = quote ! { } ; info ! ("📖 Processing all .rs files in crate...") ; println ! ("🔍 SCANNING FOR RUST FILES...") ; process_all_rust_files (paths , config , & mut collected_module_names , & mut item_count , & common_uses , false , & mut module_not_found_errors) ? ; println ! ("📊 PROCESSING SUMMARY:") ; println ! ("   📋 Total items processed: {}" , item_count) ; println ! ("   📦 Total modules generated: {}" , collected_module_names . len ()) ; println ! ("DEBUG: Before generate_output_lib_rs call.") ; generate_output_lib_rs (paths) ? ; println ! ("DEBUG: After generate_output_lib_rs call.") ; println ! ("DEBUG: Before generate_new_lib_rs call.") ; generate_new_lib_rs (paths) ? ; println ! ("DEBUG: After generate_new_lib_rs call.") ; println ! ("DEBUG: Before generate_new_build_rs call.") ; generate_new_build_rs (paths) ? ; println ! ("DEBUG: After generate_new_build_rs call.") ; info ! ("Eager splitting completed for crate: {}" , paths . crate_name) ; info ! ("Output generated in: {}" , paths . decls_output_dir . parent () . unwrap () . display ()) ; println ! ("DEBUG: Exiting eager_split_crate for crate: {}" , paths . crate_name) ; Ok (module_not_found_errors) }
}